package jp.personal.hanshinedge.ui;
import android.app.Activity;import android.os.Bundle;import android.view.View;import android.widget.*;import org.json.*;import java.util.*;import jp.personal.hanshinedge.prediction.*;import jp.personal.hanshinedge.runtime.CapabilityGate;
public final class MainActivity extends Activity {
 private LinearLayout content;private RaceRepository repository;private boolean destroyed;private int screenGeneration;
 public static final int SCREEN_ID=7001;
 @Override public void onCreate(Bundle b){super.onCreate(b);repository=new RaceRepository(this);home();}
 private void screen(String title){screenGeneration++;ScrollView scroll=new ScrollView(this);content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(24,24,24,24);content.setId(SCREEN_ID);scroll.addView(content);setContentView(scroll);label(title,24);label("REAL MONEY: BLOCKED",16);}
 private void label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setPadding(0,12,0,12);content.addView(v);}
 private void button(String name,Runnable action){Button b=new Button(this);b.setText(name);b.setOnClickListener(v->action.run());content.addView(b);}
 private String value(JSONObject x,String key){return !x.has(key)||x.isNull(key)?"UNKNOWN":x.optString(key);}
 public void home(){screen("JRA-EDGE\n本日の開催");label("現在資金 ¥100,000\nF0: NOT AVAILABLE · 正式購入0件",18);button("10万円架空運用",this::paper);button("本日の開催を更新",this::home);button("過去の公式22レースを見る（購入不可）",this::historical);TextView status=new TextView(this);status.setText("JRA公式情報を取得中…");content.addView(status);final int generation=screenGeneration;repository.today((v,e)->{if(destroyed||generation!=screenGeneration)return;if(e!=null){status.setText(e+"\n通信・公開状況を確認して更新してください。");return;}try{JSONArray ms=v.getJSONArray("meetings");status.setText(ms.length()==0?"本日公開済みの開催がありません。架空の開催は表示しません。":"競馬場を選択してください");for(int i=0;i<ms.length();i++){JSONObject m=ms.getJSONObject(i);button(m.getString("venue"),()->raceList(m));}}catch(Exception ex){status.setText("SOURCE_MISSING");}});}
 private void raceList(JSONObject meeting){screen(meeting.optString("venue")+" レース一覧");button("開催一覧",this::home);label("取得中…",16);final int generation=screenGeneration;repository.races(meeting,(v,e)->{if(destroyed||generation!=screenGeneration)return;if(e!=null){label(e,16);return;}try{JSONArray races=v.getJSONArray("races");for(int i=0;i<races.length();i++){JSONObject r=races.getJSONObject(i);button(r.optInt("race_no")+"R "+value(r,"scheduled_start")+"\n"+value(r,"race_name")+"\n"+value(r,"surface")+" "+value(r,"distance_m")+"m",()->showRace(r));}}catch(Exception ex){label("PARSER_UNSUPPORTED",16);}});}
 private void historical(){try{screen("公式Historical · REAL_PROSPECTIVE=false");button("開催一覧",this::home);JSONArray races=repository.historical();for(int i=0;i<races.length();i++){JSONObject r=races.getJSONObject(i);button(r.optString("venue")+" "+r.optInt("race_no")+"R "+r.optString("race_name"),()->showRace(r));}}catch(Exception e){label("FIXTURE_UNAVAILABLE: "+e.getMessage(),16);}}
 public void showRace(JSONObject race){try{screen(race.optString("venue")+" "+race.optInt("race_no")+"R\n"+value(race,"race_name"));button("開催一覧",this::home);for(String key:new String[]{"scheduled_start","surface","distance_m","age_condition","class_name","sex_restriction","grade"})label(key+": "+value(race,key),16);CapabilityGate.Capabilities cap=CapabilityGate.evaluate(repository.context(race));label(cap.formalPaperBuy?"FORMAL PAPER BUY ALLOWED（追加データ条件あり）":"FORMAL BUY BLOCKED: "+cap.formalBlockReason,18);PredictionProvider.Prediction p=repository.prediction(race);label("F0: "+p.f0Status+"\n判定: "+p.finalAction+"\nreason: "+p.reason,18);if(p.model==null)label("総合勝率: UNKNOWN\nEDGE: UNKNOWN\nEV: UNKNOWN\n予想データ待ち\nF0_NOT_READY",18);else for(FrozenMf0Engine.Row row:p.model.rows)label("#"+row.horseNo+" "+row.horseName+String.format(Locale.JAPAN,"\n総合勝率 %.2f%% / 市場勝率 %.2f%%\nEDGE %+.2fpt / EV %.4f",row.mf0*100,row.m0*100,row.edgePt,row.evQuote),18);
 JSONArray runners=race.optJSONArray("runners");label("出走馬 "+(runners==null?0:runners.length())+"頭",20);if(runners!=null)for(int i=0;i<runners.length();i++){JSONObject r=runners.getJSONObject(i);label("枠 "+value(r,"frame")+" / #"+value(r,"horse_no")+" "+value(r,"horse_name")+"\n"+value(r,"sex_age")+" / 斤量 "+value(r,"carried_weight_kg")+"\n単勝 "+value(r,"win_odds")+" / 人気 "+value(r,"popularity"),16);}
 label("TIMECHAIN\nT-20: NOT_YET_AVAILABLE\nT-10: NOT_YET_AVAILABLE\nT-5: NOT_YET_AVAILABLE\nT-2: NOT_YET_AVAILABLE\nBackground scheduling: NOT_CONNECTED",16);button("診断",()->new android.app.AlertDialog.Builder(this).setTitle("取得・モデル診断").setMessage(race.toString()+"\nMODEL_HASH_STATUS="+FrozenMf0Engine.MODEL_HASH_STATUS+"\nFORMAL BUY writes from UI: 0").setPositiveButton("閉じる",null).show());}catch(Exception e){label("BLOCKED: "+e.getMessage(),16);}}
 public void paper(){screen("10万円架空運用");button("開催一覧",this::home);try{JSONObject p=repository.paper();if(p.getJSONObject("formal_records").getInt("count")!=0||p.getJSONObject("settlement_records").getInt("count")!=0){label("資金・集計: UNKNOWN（台帳集計の接続待ち）",18);return;}label("現在資金 ¥100,000\n本日購入: 0円\n本日払戻: 0円\n本日損益: 0円\n累計損益: 0円\n回収率: NOT_YET_AVAILABLE\n購入件数: 0\n見送り件数: 0\n未精算件数: 0\n正式stake: NOT_AVAILABLE\n自動購入・精算UI接続: BLOCKED",18);label("Runtime audit: "+p.toString(),14);}catch(Exception e){label("BANKROLL_UNVERIFIED: "+e.getMessage(),16);}}
 @Override public void onDestroy(){destroyed=true;repository.close();super.onDestroy();}
}
